+const spill = new THREE.PointLight(0xff8a3a, 5, 7, 2); spill.position.set(0, 2.6, 0); scene.add(spill);
+
+// ---------- lamp geometry ----------
+const GLASS_Y0 = 1.02, GLASS_H = 3.05, GLASS_Y1 = GLASS_Y0 + GLASS_H;
+function vesselRadius(y) { // world y -> outer glass radius
+  const t = THREE.MathUtils.clamp((y - GLASS_Y0) / GLASS_H, 0, 1);
+  let r = THREE.MathUtils.lerp(0.94, 0.44, Math.pow(t, 0.78)) * (1 + 0.05 * Math.sin(t * Math.PI));
+  if (t > 0.86) { const k = (t - 0.86) / 0.14; r *= Math.sqrt(Math.max(0, 1 - k * k * 0.92)); }
+  if (t < 0.04) r *= 0.72 + 7 * t;
+  return Math.max(r, 0.02);
+}
+function latheFrom(profile, seg = 72) {
+  return new THREE.LatheGeometry(profile.map(p => new THREE.Vector2(p[0], p[1])), seg);
+}
+// glass: outer up, over the rim, inner down -> real visible thickness
+const glassProfile = [];
+for (let i = 0; i <= 30; i++) { const y = GLASS_Y0 + GLASS_H * i / 30; glassProfile.push([vesselRadius(y), y]); }
+for (let i = 30; i >= 0; i--) { const y = GLASS_Y0 + 0.055 + (GLASS_H - 0.1) * i / 30; glassProfile.push([Math.max(vesselRadius(y) - 0.055, 0.02), y]); }
+const glassMat = new THREE.MeshPhysicalMaterial({
+  color: 0xffffff, metalness: 0, roughness: 0.045, transmission: 0.92, thickness: 0.14, ior: 1.5,
+  clearcoat: 1, clearcoatRoughness: 0.06, transparent: true, opacity: 0.42, envMapIntensity: 1.6,
+  specularIntensity: 1.2, side: THREE.DoubleSide, depthWrite: false
+});
+const glass = new THREE.Mesh(latheFrom(glassProfile), glassMat);
+glass.renderOrder = 30; scene.add(glass);
+// tinted liquid volume just inside the glass
+const liquidProfile = [];
+for (let i = 0; i <= 26; i++) { const y = GLASS_Y0 + 0.06 + (GLASS_H - 0.16) * i / 26; liquidProfile.push([Math.max(vesselRadius(y) - 0.07, 0.02), y]); }
+liquidProfile.push([0.02, GLASS_Y1 - 0.12]);
+const liquidMat = new THREE.MeshPhysicalMaterial({
+  color: 0xffc81f, transparent: true, opacity: 0.22, roughness: 0.08, metalness: 0,
+  transmission: 0.55, thickness: 1.4, ior: 1.36, envMapIntensity: 0.5, depthWrite: false, side: THREE.DoubleSide
+});
+const liquid = new THREE.Mesh(latheFrom(liquidProfile), liquidMat);
+liquid.renderOrder = 20; scene.add(liquid);
+
+// brushed metal base + cap
+const metalMat = new THREE.MeshStandardMaterial({
+  color: 0xd9d4cc, metalness: 0.96, roughness: 0.34, roughnessMap: metalRough, envMapIntensity: 1.35
+});
+const baseProfile = [[0.02, 0], [0.98, 0], [1.04, 0.06], [1.02, 0.16], [0.82, 0.62], [0.68, 0.98], [0.72, 1.08], [0.9, 1.12], [0.92, 1.2], [0.6, 1.22], [0.02, 1.22]];
+const base = new THREE.Mesh(latheFrom(baseProfile), metalMat);
+base.castShadow = base.receiveShadow = true; scene.add(base);
+const baseTrim = new THREE.Mesh(new THREE.TorusGeometry(1.025, 0.028, 14, 80), metalMat);
+baseTrim.rotation.x = Math.PI / 2; baseTrim.position.y = 0.1; baseTrim.castShadow = true; scene.add(baseTrim);
+const capProfile = [[0.02, 0.34], [0.3, 0.34], [0.5, 0.26], [0.58, 0.1], [0.56, -0.04], [0.4, -0.1], [0.02, -0.1]];
+const cap = new THREE.Mesh(latheFrom(capProfile), metalMat);
+cap.position.y = GLASS_Y1 + 0.02; cap.castShadow = cap.receiveShadow = true; scene.add(cap);
+// heating coil hint inside the glass bottom
+const coil = new THREE.Mesh(
+  new THREE.TorusGeometry(0.42, 0.035, 10, 48),
+  new THREE.MeshStandardMaterial({ color: 0x554433, metalness: 0.9, roughness: 0.4, emissive: 0xff4400, emissiveIntensity: 0.7 })
+);
+coil.rotation.x = Math.PI / 2; coil.position.y = GLASS_Y0 + 0.14; scene.add(coil);
+// bulb
+const bulbMat = new THREE.MeshStandardMaterial({ color: 0xfff1d0, emissive: 0xffb056, emissiveIntensity: 6, roughness: 0.3 });
+const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.19, 24, 18), bulbMat);
+bulb.scale.y = 1.3; bulb.position.y = 1.28; scene.add(bulb);
+const glowSpriteMat = new THREE.SpriteMaterial({
+  map: canvasTex(128, 128, (g, w, h) => { const r = g.createRadialGradient(64, 64, 2, 64, 64, 64); r.addColorStop(0, 'rgba(255,230,190,1)'); r.addColorStop(0.35, 'rgba(255,170,80,.55)'); r.addColorStop(1, 'rgba(255,120,30,0)'); g.fillStyle = r; g.fillRect(0, 0, w, h); }),
+  transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.85
+});
+const glow = new THREE.Sprite(glowSpriteMat); glow.scale.setScalar(2.6); glow.position.y = 1.45; glow.renderOrder = 25; scene.add(glow);
+
+// physical rocker switch on the base (clickable)
