+
+// ---------- presets + controls ----------
+const PRESETS = [
+  { name: 'Classic', wax: 0xd81a08, hot: 0xffa02e, liquid: 0xffc81f, glow: 0xff7a2a },
+  { name: 'Violet deep', wax: 0x7b1fd4, hot: 0xe879f9, liquid: 0x1d4ed8, glow: 0xa04dff },
+  { name: 'Emerald', wax: 0x0aa84f, hot: 0x7dff9a, liquid: 0x0e6f8e, glow: 0x2fe07a },
+  { name: 'Sunset', wax: 0xe85d04, hot: 0xffd166, liquid: 0xc2185b, glow: 0xff8a3a },
+  { name: 'Arctic', wax: 0xe8f4ff, hot: 0x9fdcff, liquid: 0x1440a0, glow: 0x7cc4ff }
+];
+const target = { wax: new THREE.Color(PRESETS[0].wax), hot: new THREE.Color(PRESETS[0].hot), liquid: new THREE.Color(PRESETS[0].liquid), glow: new THREE.Color(PRESETS[0].glow) };
+const swWrap = document.getElementById('swatches');
+PRESETS.forEach((p, i) => {
+  const b = document.createElement('button');
+  b.className = 'sw' + (i === 0 ? ' on' : ''); b.title = p.name; b.setAttribute('aria-label', p.name);
+  b.innerHTML = `<span style="background:#${p.wax.toString(16).padStart(6, '0')}"></span><i style="background:#${p.liquid.toString(16).padStart(6, '0')}"></i>`;
+  b.onclick = () => {
+    document.querySelectorAll('.sw').forEach(s => s.classList.remove('on')); b.classList.add('on');
+    target.wax.set(p.wax); target.hot.set(p.hot); target.liquid.set(p.liquid); target.glow.set(p.glow);
+  };
+  swWrap.appendChild(b);
+});
+const $ = id => document.getElementById(id);
+function bindSlider(id, out, fn) {
+  const el = $(id);
+  const go = () => { $(out).textContent = el.value; fn(el.value / 100); };
+  el.addEventListener('input', go); go();
+}
+bindSlider('heat', 'heatV', v => state.heat = v);
+bindSlider('wax', 'waxV', v => state.waxAmt = v);
+bindSlider('room', 'roomV', v => state.room = v);
+function setPower(on) {
+  if (on && !state.on) state.warmup = 0; // cold start: wax must re-melt before the first blob rises
+  state.on = on;
+  $('power').classList.toggle('on', on);
+  rocker.material.color.set(on ? 0xff7a2a : 0x6b5a48);
+}
+$('power').onclick = () => setPower(!state.on);
+$('orbitBtn').onclick = e => { state.orbit = !state.orbit; controls.autoRotate = state.orbit; e.currentTarget.classList.toggle('on', state.orbit); };
+$('slowBtn').onclick = e => { state.slow = !state.slow; e.currentTarget.classList.toggle('on', state.slow); };
+// click the physical rocker switch on the base
+const ray = new THREE.Raycaster(), ptr = new THREE.Vector2(); let downXY = null;
+canvas.addEventListener('pointerdown', e => downXY = [e.clientX, e.clientY]);
+canvas.addEventListener('pointerup', e => {
+  if (!downXY || Math.hypot(e.clientX - downXY[0], e.clientY - downXY[1]) > 5) return;
+  ptr.set(e.clientX / innerWidth * 2 - 1, -(e.clientY / innerHeight) * 2 + 1);
+  ray.setFromCamera(ptr, camera);
+  if (ray.intersectObjects([rocker, switchBase, inlineSwitch], false).length) setPower(!state.on);
+});
+
+// ---------- post-processing ----------
+const composer = new EffectComposer(renderer);
+composer.setPixelRatio(DPR);
+composer.addPass(new RenderPass(scene, camera));
+const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 0.55, 0.55, 0.62);
+composer.addPass(bloom);
+const filmPass = new ShaderPass({
+  uniforms: { tDiffuse: { value: null }, uTime: { value: 0 } },
+  vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
+  fragmentShader: `
+    uniform sampler2D tDiffuse; uniform float uTime; varying vec2 vUv;
+    float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453); }
+    void main(){
+      vec4 c = texture2D(tDiffuse, vUv);
+      float vig = smoothstep(1.25, 0.35, length(vUv - 0.5) * 1.6);
+      c.rgb *= mix(0.72, 1.0, vig);
+      c.rgb += (hash(vUv * vec2(1920.0,1080.0) + fract(uTime)*7.0) - 0.5) * 0.032;
+      gl_FragColor = c;
+    }`
+});
+composer.addPass(filmPass);
+composer.addPass(new OutputPass());
+
+addEventListener('resize', () => {
+  camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix();
+  renderer.setSize(innerWidth, innerHeight); composer.setSize(innerWidth, innerHeight);
+});
+
+// ---------- main loop: fixed-step sim, adaptive quality ----------
+const clock = new THREE.Clock();
+let acc = 0, frames = 0, fpsTimer = 0;
+const stateEl = $('state');
+function bulbOcclusion() {
+  let occ = 0;
+  for (const b of blobs) if (b.active) occ += Math.exp(-((b.y - 1.4) ** 2) * 3.2) * Math.exp(-(b.x * b.x + b.z * b.z) * 4) * b.baseR * 2.2;
+  return THREE.MathUtils.clamp(occ, 0, 0.55);
+}
+renderer.setAnimationLoop(() => {
+  const dtReal = Math.min(clock.getDelta(), 0.05);
+  const dt = dtReal * (state.slow ? 0.22 : 1);
+  acc += dt;
+  const STEP = 1 / 60; let n = 0;
+  while (acc >= STEP && n < 4) { simStep(STEP); acc -= STEP; n++; }
+  if (n === 4) acc = 0;
+  pushUniforms();
+
+  // smooth colour-preset crossfade
+  const k = 1 - Math.exp(-dtReal * 2.2);
+  waxUniforms.uWax.value.lerp(target.wax, k); waxUniforms.uWaxHot.value.lerp(target.hot, k);
+  waxUniforms.uLiquid.value.lerp(target.liquid, k);
+  liquidMat.color.lerp(target.liquid, k);
+  bulbLight.color.lerp(target.glow, k); spill.color.lerp(target.glow, k);
+  bulbMat.emissive.lerp(target.hot, k);
+
+  // lamp-driven lighting: flickers as wax crosses the bulb
+  const occ = bulbOcclusion();
+  const flick = 1 - occ * 0.7 + Math.sin(state.time * 23.7) * 0.012 + Math.sin(state.time * 7.3) * 0.02;
+  const p = state.power * (0.25 + state.warmup * 0.75);
+  bulbLight.intensity = 34 * p * flick;
+  spill.intensity = 6 * p * (1 - occ * 0.4);
+  bulbMat.emissiveIntensity = 6 * p * flick + 0.02;
+  coil.material.emissiveIntensity = 0.9 * p;
+  glowSpriteMat.opacity = 0.8 * p * (1 - occ * 0.5);
+  glow.scale.setScalar(2.4 + 0.35 * Math.sin(state.time * 1.8) + occ * 0.4);
+  bloom.strength = 0.28 + 0.4 * p;
+  ambient.intensity = 0.05 + state.room * 0.85;
+  roomLight.intensity = state.room * 1.5;
+  scene.environmentIntensity = 0.12 + state.room * 0.7;
+  stateEl.textContent = !state.on ? 'Off — cooling' : state.warmup < 0.98 ? 'Warming…' : 'Flowing';
+
+  controls.update();
+  filmPass.uniforms.uTime.value = state.time;
+  composer.render();
+
+  // adaptive resolution: keep frame rate stable on weaker GPUs
+  frames++; fpsTimer += dtReal;
+  if (fpsTimer > 1.5) {
+    const fps = frames / fpsTimer; frames = 0; fpsTimer = 0;
+    if (fps < 42 && DPR > 0.8) { DPR = Math.max(0.8, DPR - 0.2); renderer.setPixelRatio(DPR); composer.setPixelRatio(DPR); onResizeFix(); }
+    else if (fps > 58 && DPR < Math.min(devicePixelRatio || 1, 1.75)) { DPR += 0.15; renderer.setPixelRatio(DPR); composer.setPixelRatio(DPR); onResizeFix(); }
+  }
+});
+function onResizeFix() { renderer.setSize(innerWidth, innerHeight); composer.setSize(innerWidth, innerHeight); }
+</script>
+</body>
+</html>

